public interface IClock
{
    string Now();
}

public sealed class SystemClock : IClock
{
    public string Now() => DateTime.UtcNow.ToString("HH:mm");
}

public sealed class FixedClock : IClock
{
    public string Now() => "12:00";
}

public sealed class ReportService(IClock clock)
{
    public string Header() => $"report at {clock.Now()}";
}

public static class Container
{
    private static readonly Dictionary<Type, Func<object>> Registrations = [];

    public static void Register<T>(Func<T> factory) => Registrations[typeof(T)] = () => factory()!;

    public static T Resolve<T>() => (T)Registrations[typeof(T)]();
}

public static class Demo
{
    public static string Run()
    {
        Container.Register<IClock>(() => new FixedClock());
        var service = new ReportService(Container.Resolve<IClock>());
        return service.Header();
    }
}

// Demo.Run() -> "report at 12:00"

public interface ILogger
{
    void Log(string message);
    IReadOnlyList<string> Entries { get; }
}

// Legacy SDK with an awkward API (cannot be changed)
public sealed class OldLogSdk
{
    private readonly List<string> _lines = [];
    public void WriteLine(string message, int level) => _lines.Add($"L{level}: {message}");
    public IReadOnlyList<string> Dump() => _lines;
}

public sealed class LegacyLoggerAdapter : ILogger
{
    private readonly OldLogSdk _legacy = new();

    public void Log(string message) => _legacy.WriteLine(message, level: 1);

    public IReadOnlyList<string> Entries => _legacy.Dump();
}

public static class Demo
{
    public static string Run()
    {
        ILogger logger = new LegacyLoggerAdapter();
        logger.Log("hello");
        return string.Join("|", logger.Entries); // "L1: hello"
    }
}

